package com.mathan.erp.audit;
import com.mathan.erp.security.UserPrincipal;import com.mathan.erp.tenant.TenantService;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/audit-logs") public class AuditController {private final JdbcClient db;private final TenantService tenants;public AuditController(JdbcClient d,TenantService t){db=d;tenants=t;}@GetMapping List<?> list(@AuthenticationPrincipal UserPrincipal u,@RequestHeader("X-Business-Id")String h,@RequestParam(defaultValue="100")int limit){UUID b=tenants.require(u,h,"audit").businessId();return db.sql("select a.id,a.actor_id,u.display_name actor_name,a.action,a.entity_type,a.entity_id,a.details,a.occurred_at from audit_log a left join app_user u on u.id=a.actor_id where a.business_id=:b order by a.occurred_at desc limit :l").param("b",b).param("l",Math.min(500,Math.max(1,limit))).query((rs,n)->{var m=new LinkedHashMap<String,Object>();m.put("id",rs.getObject("id",UUID.class));m.put("actorId",rs.getObject("actor_id",UUID.class));m.put("actorName",rs.getString("actor_name"));m.put("action",rs.getString("action"));m.put("entityType",rs.getString("entity_type"));m.put("entityId",rs.getObject("entity_id",UUID.class));m.put("details",rs.getString("details"));m.put("timestamp",rs.getTimestamp("occurred_at").toInstant());return m;}).list();}}

